// `.spec.` is deliberately left un-tightened: narrowing it risks regressing `foo.spec.ts` detection.
const TEST_PATH_PATTERNS = [
    /\.test\./,
    /\.spec\./,
    /_test\./,
    /(^|\/)__tests__\//,
    /_test\.go$/,
    /_test\.rs$/,
    /(^|\/)test_[^/]*\.py$/,
    /Tests?\.(java|kt)$/,
    /_spec\.rb$/,
    /Tests?\.cs$/,
    /Test\.php$/,
];
export function isTestFile(filePath) {
    return TEST_PATH_PATTERNS.some((pattern) => pattern.test(filePath));
}
const DOC_PATH_PATTERN = /\.(md|markdown|mdx|txt|rst|adoc)$/i;
export function isDocFile(filePath) {
    return DOC_PATH_PATTERN.test(filePath);
}
export function normalizeTestName(describe, it) {
    const collapse = (segment) => segment.trim().replace(/\s+/g, " ").toLowerCase();
    return [describe, it]
        .map(collapse)
        .filter((segment) => segment.length > 0)
        .join(" › ");
}

