    return { combined: combined.replace(/\s+/g, " ").trim(), endIndex: index };
}
/** Classifies a non-fence, non-blank-checked line by which segmentation action it triggers. */
function classifyStatementLine(line) {
    if (line.trim() === "") {
        return "blank";
    }
    if (isHeading(line)) {
        return "heading";
    }
    if (isTableRow(line)) {
        return "table";
    }
    if (isListItem(line)) {
